INSERT INTO "messages" ("id","community_id","sent_at","body","link_codes","delivered","reads","reactions","replies","updated_at") VALUES('true_120363411521160748@g.us_3EB0538E27EB81E6E93023_102208024637533@lid','30-aug-2026-flexi-genie-exclusive',1792646634,replace('*1,000 true fans = ₹10 lakhs/month?* 💰\n\nYou don''t need 1 lakh followers or millions of views to build a real online business. You need *1,000 true fans* who trust you and pay for the value you give.\n\n1,000 loyal customers beat 1,00,000 followers who never buy.\n\nAt ₹999/month:\n* 100 members = ₹99,900/month\n* 1,000 members = *₹9,99,000/month*\n\n*FREE LIVE SESSION: The 1,000 True Fans Blueprint*\n*Tonight, 22 Oct · 8:00 PM IST*\n\n👉 *Grab your free seat* : https://sb.flexifunnels.com/community-special\n\n*We''ll build a paid community LIVE and show you how to* :\n* Pick a niche and set your pricing\n* Turn ordinary members into loyal fans\n* Run courses, community & payments in one place\n\nNo tech team. No big audience needed.\n\nBonus: a first look at our new AI Community 🎁\n\n*Reserve your seat* : https://sb.flexifunnels.com/community-special','\n',char(10)),'',6,3,0,0,1793166231);
INSERT INTO "messages" ("id","community_id","sent_at","body","link_codes","delivered","reads","reactions","replies","updated_at") VALUES('true_120363411521160748@g.us_3EB09C70BC1B28D16AEF7C_102208024637533@lid','30-aug-2026-flexi-genie-exclusive',1792672987,replace('*₹4,00,000 once vs ₹3,99,600 every month* 💰\n\n80 people buying your ₹5,000 course pays you ₹4,00,000. Once. Next month, you need 80 new sales to do it again.\n\n400 members paying ₹999/month bring in *₹3,99,600 every month* while they stay active.\n\n👉 *Final call to register(Just 2 Hours Left):* https://sb.flexifunnels.com/community-special \n\nWe''ll build a paid community LIVE, from a blank screen.\n\n*FREE LIVE SESSION: The Monthly Income Blueprint*\n*Time: 8:00 PM IST (10:30 AM ET)*\n\n*Secure your seat*: https://sb.flexifunnels.com/community-special','\n',char(10)),'',6,3,0,0,1793166231);
INSERT INTO "messages" ("id","community_id","sent_at","body","link_codes","delivered","reads","reactions","replies","updated_at") VALUES('true_120363411521160748@g.us_3EB03CDB8E592F77D78A33_102208024637533@lid','30-aug-2026-flexi-genie-exclusive',1792679551,replace('*We''re LIVE now!* 🔴\n\nThe 1000 Follower Income Blueprint session has started, and we''re building a paid community from a blank screen right now.\n\nLearn how *400 members at ₹999 can mean ₹3,99,600/month*.\n\n👉 *Join now:* https://us06web.zoom.us/webinar/register/WN_x0B0K4aIQeOEm_Q5U8flLg\n\nThe AI Community reveal is coming up during the session. Don''t miss it.','\n',char(10)),'',6,3,0,0,1793166231);
