INSERT INTO "messages" ("id","community_id","sent_at","body","link_codes","delivered","reads","reactions","replies","updated_at") VALUES('true_120363413706041255@g.us_3EB07A69578A445ED6DE78_102208024637533@lid','28-oct-2026-7-30-pm-10-minutes-business-',1793161984,replace('☀️ *GOOD MORNING, EVERYONE!*\n\n🔥 *TONIGHT! At 7:30 PM, we’re about to show you something that could completely change the way you think about building a business.*\n\n🚀 10 MINUTES. ONE CONVERSATION. ONE BUSINESS — LIVE.\n\nYou’ll see Flexi Genie turn an idea into a website, product, checkout & payments — right from a phone.\n\n🤯 This isn’t another session you just listen to. You’re going to SEE IT HAPPEN.\n\n⏰ *28 October • 7:30 PM IST*\n\nCome ready. Today is going to be BIG! 🔥\n\n*P.S. We''ll give you exclusive access to the AI Business Builder Tool so you can implement the exact process with us live, step-by-step today at 5:30 PM.*','\n',char(10)),'',231,57,0,0,1793167602);
